import { readFile } from "node:fs/promises";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { emitModels, writeGenerated } from "./lib/contract-codegen.mjs";
const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const input = JSON.parse(
  await readFile(path.join(root, "contracts/pharmacy-accounts.json"), "utf8"),
);
const models = emitModels(input.models);
await writeGenerated(
  root,
  "backend/internal/modules/pharmacy/accounts_types_generated.go",
  '// Code generated by scripts/generate-pharmacy-accounts.mjs; DO NOT EDIT.\npackage pharmacy\nimport("time";"github.com/google/uuid")\n' +
    models.go,
  "packages/api/src/pharmacy-accounts-contract.ts",
  '// Code generated by scripts/generate-pharmacy-accounts.mjs; DO NOT EDIT.\nimport{z}from"zod";\n' +
    models.ts,
  "Pharmacy accounts",
);
